#include <filesystem>
#include "general_double_fftw_backend.h"
#include <fstream>
#include <iostream>
#include <iomanip>
#include <bit>
namespace fs=std::filesystem;using namespace IQM::HDRVDP3;
std::vector<double> read(const fs::path&p,size_t n){if(fs::file_size(p)!=n*8)throw std::runtime_error("Input shape: "+p.string());std::vector<double> v(n);std::ifstream f(p,std::ios::binary);if(!f.read(reinterpret_cast<char*>(v.data()),std::streamsize(n*8)))throw std::runtime_error("Read failed");return v;}
void save(const fs::path&p,const std::vector<double>&v){std::ofstream f(p,std::ios::binary);f.write(reinterpret_cast<const char*>(v.data()),std::streamsize(v.size()*8));if(!f)throw std::runtime_error("Write failed");}
int main(int argc,char**argv){try{const bool scoreOnly=argc==6&&std::string(argv[5])=="--scores-only";if(argc!=5&&!scoreOnly)throw std::runtime_error("Usage: case-directory model-directory fftw-dll fresh-output [--scores-only]");fs::path source=argv[1],data=argv[2],out=argv[4];if(fs::exists(out)||!fs::create_directories(out))throw std::runtime_error("Fresh output required");GeneralQualityConfigDouble config;std::string encoding,display;std::ifstream metadata(source/"config.txt");if(!(metadata>>config.width>>config.height>>config.ppd>>config.age>>encoding>>display))throw std::runtime_error("Case metadata");if(encoding=="sRGB-display")config.encoding=GeneralEncodingDouble::SRGBDisplay;else if(encoding=="rgb-bt.709")config.encoding=GeneralEncodingDouble::BT709;else if(encoding=="rgb-bt.2020")config.encoding=GeneralEncodingDouble::BT2020;else if(encoding=="XYZ")config.encoding=GeneralEncodingDouble::XYZ;else if(encoding!="rgb-native")throw std::runtime_error("Unsupported Double encoding");size_t n=size_t(config.width)*config.height;const auto reference=read(source/"reference.f64",3*n),test=read(source/"test.f64",3*n);auto xyz=load_xyz_display_samples(data/"ciexyz31.csv",data/("emission_spectra_"+display+".csv"));auto spectral=load_rgb_spectral_samples(data/"log_cone_smith_pokorny_1975.csv",data/"cie_scotopic_lum.txt",data/("emission_spectra_"+display+".csv"));GeneralFFTW fft(argv[3]);GeneralQualityTraceDouble trace;auto result=evaluate_general_quality_double(reference,test,config,xyz,spectral,fft.backend(),scoreOnly?nullptr:&trace);std::ofstream scores(out/"quality.txt");scores<<std::setprecision(17);for(double e:result.band_errors)scores<<e<<' ';scores<<'\n'<<result.scores.error<<' '<<result.scores.Q<<' '<<result.scores.Q_JOD<<'\n';scores.close();if(scoreOnly){std::cout<<"Independent C++ Double CPU quality;Q="<<std::setprecision(17)<<result.scores.Q<<" Q_JOD="<<result.scores.Q_JOD<<char(10);return 0;}std::ofstream comparisons(out/"comparisons.tsv");size_t total=0,errors=0;auto compare=[&](std::string name,const std::vector<double>&actual){save(out/(name+".f64"),actual);auto gold=read(source/(name+".f64"),actual.size());size_t differences=0;for(size_t i=0;i<gold.size();++i)differences+=std::bit_cast<uint64_t>(gold[i])!=std::bit_cast<uint64_t>(actual[i]);comparisons<<name<<'\t'<<differences<<'/'<<gold.size()<<'\n';total+=gold.size();errors+=differences;};
 for(auto item:{std::pair{"reference",&trace.reference},std::pair{"test",&trace.test}}){std::string name=item.first;const auto& side=*item.second;compare(name+"_rgb",side.rgb);compare(name+"_adaptation",side.adaptation);compare(name+"_P",side.response);for(size_t b=0;b<side.pyramid.bands.size();++b)compare(name+"_band"+std::to_string(b+1),side.pyramid.bands[b].values);}
 compare("mean_log",trace.mean_log);for(size_t b=0;b<result.band_errors.size();++b)compare("band"+std::to_string(b+1)+"_error",{result.band_errors[b]});compare("scores",{result.scores.Q,result.scores.Q_JOD});std::ofstream(out/"results.txt")<<errors<<" bit errors /"<<total<<" compared Double words\n";std::cout<<errors<<" bit errors /"<<total<<" words;Q="<<std::setprecision(17)<<result.scores.Q<<" Q_JOD="<<result.scores.Q_JOD<<'\n';return errors?2:0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
